package dev.zomboid.tacz;
import java.lang.reflect.*;
public final class Weather {
 static long testEnd;static int mode; // 0 automatic, 1 test, -1 disabled
 public static double cycle(long time){long phase=Math.floorMod(time-24000,72000);if(phase>=6000)return 0;return Math.min(1,Math.min(phase/600d,(6000-phase)/600d));}
 static double strength(){if(mode<0)return 0;if(mode==1){if(System.nanoTime()<testEnd)return 1;mode=0;}Object level=R.get(Bridge.mc(),"level");return level==null?0:cycle(((Number)R.call(level,"getGameTime")).longValue());}
 public static void fog(Object event){try{double s=strength();if(s<=0||!R.call(event,"getType").toString().equals("NONE")||!R.call(event,"getMode").toString().equals("FOG_TERRAIN"))return;float far=(float)R.num(R.call(event,"getFarPlaneDistance")),near=(float)R.num(R.call(event,"getNearPlaneDistance"));R.call(event,"setFarPlaneDistance",(float)(far+(Math.min(far,64)-far)*s));R.call(event,"setNearPlaneDistance",(float)Math.max(0,near+(Math.min(near,3)-near)*s));R.call(event,"setCanceled",true);}catch(Throwable e){Bridge.warn("periodic atmospheric fog",e);}}
 public static void color(Object event){try{double s=strength();if(s<=0)return;String[] get={"getRed","getGreen","getBlue"},set={"setRed","setGreen","setBlue"};double[] target={.55,.59,.60};for(int i=0;i<3;i++){double value=R.num(R.call(event,get[i]));R.call(event,set[i],(float)(value+(target[i]-value)*s*.7));}}catch(Throwable e){Bridge.warn("fog color",e);}}
 public static void commands(Object event){try{Object root=R.call(R.type("com.mojang.brigadier.builder.LiteralArgumentBuilder"),"literal","zomboidfog");for(String name:new String[]{"prueba","auto","off"}){Object command=R.call(R.type("com.mojang.brigadier.builder.LiteralArgumentBuilder"),"literal",name);Class<?> api=R.type("com.mojang.brigadier.Command");Object handler=Proxy.newProxyInstance(api.getClassLoader(),new Class<?>[]{api},(proxy,method,args)->{if(method.getName().equals("run")){mode=name.equals("off")?-1:name.equals("prueba")?1:0;testEnd=System.nanoTime()+90_000_000_000L;Object player=R.get(Bridge.mc(),"player");if(player!=null)R.call(player,"displayClientMessage",R.call(R.type("net.minecraft.network.chat.Component"),"literal","Niebla: "+name+(mode==1?" (90 segundos)":"")),false);return 1;}if(method.getName().equals("toString"))return "ZomboidFogCommand";if(method.getName().equals("hashCode"))return System.identityHashCode(proxy);return proxy==args[0];});R.call(command,"executes",handler);R.call(root,"then",command);}R.call(R.call(event,"getDispatcher"),"register",root);}catch(Throwable e){Bridge.warn("fog test commands",e);}}
}
